// RACCONTO GUIDATO — scenario probabile (bozza del 29/10/2026: immagini e autori da verificare su Commons)
SAP.scenari.unshift({
 id: "racconto-prob", scen: "prob", futuro: true, title: "Racconto: il mondo che cambia", sub: "Scenario probabile: le politiche di oggi, circa +2,7 °C nel 2100",
 from: 0, to: -1, unit: "anni", color: "#d19a1c",
 dom: [0, -0.000024, -0.000074, -0.000274, -0.01, -0.1, -1], rng: [0, .2, .45, .62, .78, .9, 1],
 intro: "Che cosa succede se il mondo continua più o meno con le politiche di oggi? Il riscaldamento arriva a circa 2,6–2,8 °C nel 2100 (UNEP 2025). Non è la fine del mondo, ma è un mondo diverso: alcune specie scompaiono, molte si spostano, altre si adattano in modi sorprendenti. Segui le tappe: il globo ti porta nei luoghi dove succede.",
 steps: [
  {t: 0, title: "2026: il punto di partenza", view: [10, 30, 1.1], certezza: "alta",
   img: {file: "File:Keeling Curve full record.png", author: "Scripps Institution of Oceanography", lic: "CC BY-SA 4.0", cap: "La curva di Keeling: la CO₂ nell'aria misurata a Mauna Loa (Hawaii) dal 1958", tipo: "grafico"},
   text: "La Terra è circa 1,4 °C più calda dell'Ottocento e il 2024 ha superato per la prima volta 1,5 °C. La CO₂ nell'aria supera 425 parti per milione: non era così alta da milioni di anni. Con le politiche di oggi il riscaldamento arriverebbe a circa 2,6–2,8 °C nel 2100.",
   oggi: "L'Accordo di Parigi (2015) chiede di restare «ben sotto» 2 °C; il rapporto UNEP sul divario delle emissioni (2025) calcola che le politiche attuali portano a circa 2,8 °C.",
   curiosita: "Charles David Keeling iniziò le misure nel 1958 con strumenti costruiti da lui: la sua curva a dente di sega mostra anche il «respiro» delle piante, che in primavera assorbono CO₂.",
   fonti: ["UNEP Emissions Gap Report 2025", "WMO State of the Global Climate 2024"]},
  {t: -0.000002, title: "Il grande sbiancamento dei coralli", view: [147, -18, 3.5], certezza: "alta", species: ["corallo-corno-alce"],
   img: {file: "File:Extensive bleaching in the Great Barrier Reef (Copernicus 2024-03-05).jpg", author: "Unione Europea, Copernicus Sentinel-2", lic: "Attribuzione", cap: "Grande Barriera Corallina, marzo 2024: le macchie chiare sono coralli sbiancati", tipo: "foto"},
   text: "Dal 2023 è in corso il quarto sbiancamento globale dei coralli, il più grande mai visto: ha colpito più dell'80% delle barriere del mondo. Quando l'acqua resta troppo calda, i coralli espellono le alghe che li nutrono e diventano bianchi. Se il caldo dura, muoiono.",
   oggi: "Il Global Tipping Points Report 2025 considera già superato il punto di non ritorno delle barriere coralline tropicali.",
   curiosita: "I colori dei coralli vengono in gran parte dalle alghe microscopiche (zooxantelle) che vivono dentro di loro: senza di esse si vede lo scheletro bianco.",
   fonti: ["NOAA Coral Reef Watch 2024–2025", "Lenton et al., Global Tipping Points Report 2025"]},
  {t: -0.000006, title: "Il pesce scorpione arriva in Sicilia", view: [14.5, 37, 5], certezza: "alta", species: ["fut-pesce-scorpione"],
   img: {file: "File:Pterois miles 2.jpg", author: "Vasilis Andreou", lic: "CC BY-SA 4.0", cap: "Pesce scorpione (Pterois miles), specie del Mar Rosso", tipo: "foto"},
   text: "Il Mediterraneo si scalda più in fretta degli oceani. Specie tropicali entrate dal Canale di Suez, come il pesce scorpione, risalgono fino alla Sicilia e alla Puglia. È la «tropicalizzazione»: il nostro mare cambia abitanti.",
   oggi: "Il regolamento europeo sulle specie esotiche invasive (UE 1143/2014) e la rete di segnalazione dei pescatori aiutano a seguire gli arrivi.",
   curiosita: "Le sue spine sono velenose, ma la carne è buona: in alcuni paesi si organizzano gare di pesca e ricette per tenerlo sotto controllo.",
   fonti: ["Azzurro et al. 2022, Global Change Biology", "Dimitriadis et al. 2020, Mediterranean Marine Science"]},
  {t: -0.000009, title: "Addio vaquita", view: [-114.6, 31.1, 5.5], certezza: "media", extinct: ["vaquita"],
   img: {file: "File:Vaquita6 Olson NOAA.jpg", author: "Paula Olson, NOAA", lic: "Pubblico dominio", cap: "Vaquite fotografate nel Golfo di California (NOAA)", tipo: "foto"},
   text: "Nel Golfo di California restano meno di dieci vaquite. Muoiono impigliate nelle reti messe di nascosto per pescare il totoaba, un pesce la cui vescica natatoria vale moltissimo sul mercato nero. In questo scenario i controlli non bastano e verso il 2035 la vaquita scompare: il primo cetaceo estinto dopo il delfino del fiume Yangtze.",
   oggi: "Il Messico ha creato una zona di tolleranza zero per le reti; la CITES vieta il commercio internazionale del totoaba.",
   curiosita: "È lunga circa un metro e mezzo e ha cerchi scuri attorno agli occhi: per questo la chiamano «il panda del mare».",
   fonti: ["IUCN Red List: Phocoena sinus (CR)", "Rojas-Bracho et al., rapporti CIRVA"]},
  {t: -0.000012, title: "La Marmolada senza ghiacciaio", view: [11.86, 46.43, 6], certezza: "alta", species: ["stambecco"],
   img: {file: "File:Marmolada glacier.jpg", author: "autore non indicato", lic: "Pubblico dominio", cap: "Il ghiacciaio della Marmolada, il più grande delle Dolomiti", tipo: "foto"},
   text: "Il ghiacciaio della Marmolada perde spessore ogni estate. Il 3 luglio 2022 un pezzo si staccò e uccise undici persone. I glaciologi stimano che possa sparire quasi del tutto prima del 2040: le Alpi italiane perdono così le loro riserve d'acqua per l'estate.",
   oggi: "Il Comitato Glaciologico Italiano misura i ghiacciai ogni anno; l'ONU ha dichiarato il 2025 «Anno internazionale della conservazione dei ghiacciai».",
   curiosita: "Dentro il ghiaccio della Marmolada si trovano ancora resti della Prima guerra mondiale, quando gli austriaci scavarono una «città di ghiaccio».",
   fonti: ["Comitato Glaciologico Italiano", "Carturan et al., studi sulla Marmolada"]},
  {t: -0.00002, title: "La prima estate artica senza ghiaccio", view: [0, 85, 2], certezza: "media", species: ["orso-polare"],
   img: {file: "File:Arctic Sea Ice Minimum 2025 (SVS5583).png", author: "NASA Scientific Visualization Studio", lic: "Pubblico dominio", cap: "Il ghiaccio marino artico al minimo di settembre 2025 (NASA)", tipo: "mappa"},
   text: "In un settembre degli anni 2040 il Mar Glaciale Artico resta quasi senza ghiaccio per la prima volta da migliaia di anni. Le navi possono passare sopra il Polo, ma orsi polari, foche e trichechi perdono la piattaforma su cui cacciano e partoriscono.",
   oggi: "Secondo l'IPCC (AR6) l'Artico sarà «praticamente senza ghiaccio» a settembre almeno una volta prima del 2050, in tutti gli scenari.",
   curiosita: "Il ghiaccio bianco riflette la luce del Sole; il mare scuro la assorbe: per questo l'Artico si scalda quasi quattro volte più in fretta del resto del pianeta.",
   fonti: ["IPCC AR6 WGI, SPM", "Rantanen et al. 2022, Communications Earth & Environment"]},
  {t: -0.000024, title: "La nacchera di mare scompare", view: [17.9, 40.7, 5.5], certezza: "media", extinct: ["pinna-nobilis"],
   img: {file: "File:Pinna nobilis - Torre Guaceto.jpg", author: "Ferdinando Traversa", lic: "CC BY-SA 4.0", cap: "Pinna nobilis nella riserva di Torre Guaceto (Puglia)", tipo: "foto"},
   text: "Dal 2016 un parassita ha ucciso quasi tutte le nacchere del Mediterraneo, il più grande mollusco bivalve del nostro mare. Le acque più calde favoriscono la malattia. In questo scenario le ultime popolazioni, nelle lagune, non resistono e la specie si estingue in natura verso il 2050.",
   oggi: "La specie è «in pericolo critico» per la IUCN dal 2019; in Italia e in Spagna si allevano esemplari sopravvissuti per salvarla.",
   curiosita: "Con i filamenti della nacchera (il bisso) nell'antichità si tesseva la «seta di mare»: in Sardegna, a Sant'Antioco, quest'arte si tramanda ancora.",
   fonti: ["Vázquez-Luis et al. 2017, Journal of Invertebrate Pathology", "IUCN Red List: Pinna nobilis (CR)"]},
  {t: -0.000034, title: "I Caraibi perdono i loro coralli più belli", view: [-80.6, 25, 4.5], certezza: "media", extinct: ["corallo-corno-alce", "corallo-corno-cervo"], species: ["fut-corallo-resistente"],
   img: {file: "File:FKNMS - coral nursery (27367671414).jpg", author: "NOAA National Marine Sanctuaries", lic: "Pubblico dominio", cap: "Un vivaio di coralli nelle Florida Keys", tipo: "foto"},
   text: "Nel 2023 l'acqua attorno alla Florida superò i 38 °C, come in una vasca da bagno. I coralli corna d'alce e corna di cervo, che costruivano le barriere caraibiche, scompaiono quasi del tutto verso il 2060. Restano i vivai: coralli più resistenti al caldo, selezionati dagli scienziati, che forse un giorno ripopoleranno il mare.",
   oggi: "Il programma «Mission: Iconic Reefs» della NOAA ripianta coralli nelle Florida Keys; la ricerca sull'evoluzione assistita cerca coralli tolleranti al calore.",
   curiosita: "I coralli si possono «tagliare» come le talee delle piante: ogni frammento ricresce e diventa una nuova colonia.",
   fonti: ["NOAA 2023 Florida marine heatwave", "van Oppen et al. 2015, PNAS"]},
  {t: -0.000035, title: "L'ultimo rinoceronte di Sumatra", view: [105.8, -4.9, 5], certezza: "media", extinct: ["rinoceronte-sumatra"],
   img: {file: "File:Sumatran Rhino 2.jpg", author: "Charles W. Hardin", lic: "CC BY 2.0", cap: "Rinoceronte di Sumatra, il più piccolo e peloso dei rinoceronti", tipo: "foto"},
   text: "Ne restano poche decine, divisi in piccoli gruppi nelle foreste di Sumatra e del Borneo. Gli animali sono così pochi e lontani che faticano a incontrarsi e a riprodursi. In questo scenario gli ultimi esemplari muoiono verso il 2060.",
   oggi: "In Indonesia un santuario a Way Kambas fa nascere cuccioli in cattività; l'IUCN lo classifica «in pericolo critico».",
   curiosita: "È il parente vivente più stretto del rinoceronte lanoso dell'era glaciale: anche lui ha il corpo coperto di peli rossicci.",
   fonti: ["IUCN Red List: Dicerorhinus sumatrensis (CR)", "Liu et al. 2021, Current Biology"]},
  {t: -0.00004, title: "Gli animali salgono di quota", view: [7.3, 45.55, 5.5], certezza: "media", species: ["stambecco", "pernice-bianca"],
   img: {file: "File:Capra ibex in Gran Paradiso National Park.jpg", author: "Irene Vercellino", lic: "CC BY-SA 4.0", cap: "Stambecchi nel Parco Nazionale del Gran Paradiso", tipo: "foto"},
   text: "Con il caldo, piante e animali di montagna salgono verso l'alto, ma la montagna finisce. Gli stambecchi del Gran Paradiso hanno già cambiato abitudini: nei giorni più caldi pascolano di notte. Chi non può salire o adattarsi, come la pernice bianca, perde spazio.",
   oggi: "Il Parco Nazionale del Gran Paradiso, nato nel 1922 per salvare lo stambecco, studia da decenni gli effetti del clima sulla fauna alpina.",
   curiosita: "All'inizio del Novecento gli stambecchi erano ridotti a un centinaio, tutti nel Gran Paradiso: quasi tutti quelli delle Alpi di oggi discendono da loro.",
   fonti: ["Brivio et al. 2024, Proceedings of the Royal Society B", "Lenoir et al. 2020, Nature Ecology & Evolution"]},
  {t: -0.000058, title: "Il picco della popolazione umana", view: [20, 10, 1.2], certezza: "media",
   text: "Verso la metà degli anni 2080 la popolazione mondiale raggiunge il massimo, circa 10,3 miliardi, poi comincia lentamente a calare. Le persone vivono più a lungo ma nascono meno bambini, soprattutto dove le ragazze studiano di più.",
   oggi: "Le Prospettive della popolazione mondiale dell'ONU (2024) prevedono il picco verso il 2084.",
   curiosita: "Già oggi in più di metà dei paesi del mondo nascono in media meno di 2,1 figli per donna, il numero che serve a mantenere stabile la popolazione.",
   fonti: ["UN World Population Prospects 2024"]},
  {t: -0.00006, title: "Venezia: il MOSE quasi sempre chiuso", view: [12.33, 45.43, 6.5], certezza: "media",
   img: {file: "File:03 movimento paratoie.jpg", author: "Consorzio Venezia Nuova", lic: "CC BY-SA 3.0", cap: "Le paratoie del MOSE si alzano per chiudere la laguna", tipo: "foto"},
   text: "Il MOSE, le paratoie mobili che chiudono la laguna, si alza quando la marea supera 110 cm. Con il mare più alto si chiude sempre più spesso: se restasse chiuso a lungo, l'acqua della laguna non si cambierebbe più. Venezia dovrà scegliere nuove difese.",
   oggi: "Il MOSE funziona dal 2020; l'UNESCO segue Venezia, patrimonio dell'umanità, anche per i rischi del mare che sale.",
   curiosita: "Le paratoie sono 78 e restano nascoste sul fondale: si alzano pompando aria al loro interno, come i palloncini.",
   fonti: ["IPCC AR6 WGI, capitolo 9", "Lionello et al. 2021, Natural Hazards and Earth System Sciences"]},
  {t: -0.000074, title: "2100: due specie di grandi mammiferi in meno", view: [99, 1.6, 4.5], certezza: "media", extinct: ["orango-tapanuli", "rinoceronte-giava"],
   img: {file: "File:Pongo tapanuliensis female.jpg", author: "Tim Laman", lic: "CC BY 4.0", cap: "Femmina di orango di Tapanuli, la specie di grande scimmia descritta nel 2017", tipo: "foto"},
   text: "L'orango di Tapanuli, scoperto solo nel 2017, vive in una sola foresta di Sumatra e ne restano meno di 800. Il rinoceronte di Giava sopravvive in un unico parco. Strade, dighe e bracconaggio bastano a cancellarli entro la fine del secolo in questo scenario.",
   oggi: "Il quadro mondiale per la biodiversità di Kunming-Montréal (2022) chiede di fermare le estinzioni causate dall'uomo entro il 2030.",
   curiosita: "L'orango di Tapanuli è stata la prima nuova specie di grande scimmia descritta dal 1929, quando fu riconosciuto il bonobo.",
   fonti: ["Nater et al. 2017, Current Biology", "IUCN Red List: Pongo tapanuliensis, Rhinoceros sondaicus (CR)"]},
  {t: -0.000075, title: "Il mondo del 2100", view: [12.3, 44.9, 5], certezza: "media",
   img: {file: "File:Drought grips northern Italy (Copernicus).jpg", author: "Unione Europea, Copernicus Sentinel-2", lic: "Attribuzione", cap: "Il Po in secca, vista dal satellite (Copernicus)", tipo: "foto"},
   text: "Nel 2100 la Terra è circa 2,7 °C più calda dell'Ottocento e il mare è salito di circa mezzo metro. In Pianura Padana estati più secche alternano piogge violente; nel delta del Po l'acqua salata risale il fiume per decine di chilometri. Molte città hanno imparato a convivere con il caldo: più alberi, tetti chiari, case diverse.",
   oggi: "L'Italia ha approvato nel 2023 il Piano nazionale di adattamento ai cambiamenti climatici (PNACC).",
   curiosita: "Nell'estate 2022 l'acqua salata risalì il Po per circa 40 km, la distanza più lunga mai misurata.",
   fonti: ["IPCC AR6 WGI e WGII", "Autorità di bacino distrettuale del fiume Po"]},
  {t: -0.000124, title: "La corrente atlantica rallenta", view: [-30, 50, 1.6], certezza: "bassa",
   img: {file: "File:Atlantic Meridional Overturning Circulation at weakest point in a millennium.jpg", author: "Unione Europea, Copernicus Marine Service", lic: "Attribuzione", cap: "La circolazione atlantica (AMOC): acqua calda verso nord in superficie, fredda verso sud in profondità", tipo: "mappa"},
   text: "La corrente che porta acqua calda dai tropici verso l'Europa (AMOC) si indebolisce, perché l'acqua dolce dei ghiacci rende il mare del Nord più leggero. Quanto e quando sono molto discussi: alcuni studi temono un collasso in questo secolo, altri lo ritengono improbabile prima del 2100.",
   oggi: "L'IPCC (AR6) considera «molto probabile» l'indebolimento e improbabile un collasso prima del 2100, con fiducia media.",
   curiosita: "Questa corrente trasporta ogni secondo circa cento volte l'acqua di tutti i fiumi del mondo messi insieme.",
   fonti: ["IPCC AR6 WGI", "Ditlevsen & Ditlevsen 2023, Nature Communications", "Baker et al. 2025, Nature"]},
  {t: -0.000125, title: "La balena franca nordatlantica", view: [-66, 43, 3.5], certezza: "media", extinct: ["balena-franca-nordatlantica"],
   img: {file: "File:Eubalaena glacialis with calf.jpg", author: "NOAA", lic: "Pubblico dominio", cap: "Balena franca nordatlantica con il suo piccolo", tipo: "foto"},
   text: "Ne restano meno di 400. Muoiono urtate dalle navi o impigliate nelle corde delle trappole per aragoste, e il cibo si sposta verso nord con il mare più caldo. In questo scenario la specie si spegne lentamente verso il 2150.",
   oggi: "Stati Uniti e Canada impongono limiti di velocità alle navi nelle zone dove passano le balene.",
   curiosita: "In inglese si chiama «right whale», la balena «giusta» da cacciare: era lenta e galleggiava da morta. Per questo fu quasi sterminata.",
   fonti: ["NOAA Fisheries 2024", "IUCN Red List: Eubalaena glacialis (CR)"]},
  {t: -0.000174, title: "L'orso polare perde il suo mare", view: [-85, 74, 2.8], certezza: "media", extinct: ["orso-polare"], species: ["fut-pizzly"],
   img: {file: "File:Polar bear on sea ice (52791040875).jpg", author: "USFWS Alaska", lic: "Pubblico dominio", cap: "Orso polare sul ghiaccio marino", tipo: "foto"},
   text: "Con estati senza ghiaccio sempre più lunghe gli orsi polari digiunano per mesi. Le ultime popolazioni resistono nell'arcipelago artico canadese, poi scompaiono verso il 2200. Intanto al sud gli orsi bruni salgono verso nord e nascono ibridi, i «pizzly»: un adattamento, ma non un salvataggio.",
   oggi: "L'accordo internazionale per la conservazione dell'orso polare (1973) lega Canada, Groenlandia/Danimarca, Norvegia, Russia e Stati Uniti.",
   curiosita: "Il pelo dell'orso polare non è bianco: è trasparente e cavo. Sotto, la pelle è nera per assorbire il calore del Sole.",
   fonti: ["Molnár et al. 2020, Nature Climate Change", "IUCN Polar Bear Specialist Group"]},
  {t: -0.000274, title: "2300: le isole basse", view: [73.5, 4.2, 6], certezza: "media",
   img: {file: "File:Hulhumale, Maldives (hulhumale).jpg", author: "NASA/USGS Landsat", lic: "Pubblico dominio", cap: "Hulhumalé, l'isola costruita dalle Maldive più in alto del mare", tipo: "foto"},
   text: "Il mare continua a salire anche quando le temperature si fermano: nel 2300 è da mezzo metro a più di due metri più alto di oggi. Le Maldive si spostano sulle isole artificiali più alte; altri arcipelaghi, come Tuvalu, si affidano a trattati di migrazione con i paesi vicini.",
   oggi: "Con il trattato Falepili (2023) l'Australia offre ogni anno la residenza a un gruppo di abitanti di Tuvalu per motivi climatici.",
   curiosita: "Nel 2009 il governo delle Maldive tenne una riunione sott'acqua, con le mute da sub, per chiedere al mondo di ridurre le emissioni.",
   fonti: ["IPCC AR6 WGI, capitolo 9", "Trattato Falepili Australia-Tuvalu 2023"]},
  {t: -0.01, title: "Diecimila anni dopo: l'Adriatico avanza", view: [12.5, 45, 4], certezza: "bassa",
   text: "La CO₂ in più resta nell'aria per millenni e le calotte continuano a sciogliersi lentamente: il mare può essere molti metri più alto di oggi. Le coste basse, come quelle della Pianura Padana, si spostano verso l'interno. Le specie che sono sopravvissute si sono distribuite in un mondo nuovo.",
   oggi: "L'IPCC ricorda che parte dell'innalzamento del mare è già «inevitabile» per secoli, qualunque cosa facciamo.",
   curiosita: "Durante l'ultimo periodo caldo, circa 125 000 anni fa, il mare era 6–9 metri più alto di oggi.",
   fonti: ["Clark et al. 2016, Nature Climate Change", "IPCC AR6 WGI"]},
  {t: -0.3, title: "La glaciazione rimandata", view: [-85, 60, 1.5], certezza: "media",
   img: {file: "File:Northern icesheet hg.png", author: "Hannes Grobe/AWI", lic: "CC BY 2.5", cap: "Le calotte dell'ultima glaciazione nell'emisfero nord", tipo: "mappa"},
   text: "Senza di noi la prossima glaciazione sarebbe arrivata fra circa 50 000 anni. La CO₂ che abbiamo emesso la rimanda: in questo scenario arriva fra 100 000 e 500 000 anni. Poi i ghiacci tornano a coprire il Canada e il Nord Europa e il mare si abbassa di decine di metri.",
   oggi: "Gli studi sui cicli di Milanković e sulla CO₂ (Ganopolski 2016) mostrano che le nostre emissioni lasciano un segno per centinaia di migliaia di anni.",
   curiosita: "L'ultima volta che i ghiacci erano al massimo, 20 000 anni fa, si poteva andare a piedi dall'Italia alla Croazia attraverso il nord dell'Adriatico.",
   fonti: ["Ganopolski et al. 2016, Nature", "Talento & Ganopolski 2021, Earth System Dynamics"]},
  {t: -1, title: "Un milione di anni", view: [20, 10, 1], certezza: "ipotesi", species: ["fut-sapiens-terra"],
   text: "Una specie di mammifero vive in media da uno a qualche milione di anni. Homo sapiens potrebbe esserci ancora, essere cambiato in qualcosa di diverso o essere scomparso. Intanto la vita, come dopo ogni grande crisi, avrà riempito di nuove specie gli spazi lasciati vuoti.",
   oggi: "L'articolo 9 della Costituzione italiana, modificato nel 2022, tutela l'ambiente e la biodiversità «anche nell'interesse delle future generazioni».",
   curiosita: "Dopo l'estinzione dei dinosauri ci vollero circa 10 milioni di anni perché la biodiversità tornasse ai livelli di prima.",
   fonti: ["Barnosky et al. 2011, Nature", "Kirchner & Weil 2000, Nature"]}
 ],
 markers: [
  {lat: 31.0, lon: -114.5, label: "Rifugio della vaquita", kind: "evento", from: -0.000005, to: -0.000012, taxon: "vaquita", text: "Alto Golfo di California: l'ultimo luogo dove vive la vaquita."},
  {lat: 46.43, lon: 11.86, label: "Ghiacciaio della Marmolada", kind: "sito", from: -0.000009, to: -0.000016, text: "Il più grande ghiacciaio delle Dolomiti, in rapida ritirata."},
  {lat: 40.7, lon: 17.9, label: "Torre Guaceto", kind: "sito", from: -0.00002, to: -0.000028, taxon: "pinna-nobilis", text: "Riserva marina in Puglia dove si studiava la nacchera."},
  {lat: 45.43, lon: 12.33, label: "MOSE di Venezia", kind: "sito", from: -0.000055, to: -0.000065, text: "Le paratoie mobili che difendono la laguna."},
  {lat: 1.6, lon: 99.2, label: "Foresta di Batang Toru", kind: "sito", from: -0.00007, to: -0.000078, taxon: "orango-tapanuli", text: "L'unica foresta dove vive l'orango di Tapanuli."},
  {lat: 4.2, lon: 73.54, label: "Hulhumalé", kind: "sito", from: -0.00025, to: -0.0003, text: "Isola artificiale delle Maldive, costruita più in alto del mare."}
 ]});
// RACCONTO GUIDATO — scenario pessimistico (bozza del 29/10/2026: immagini e autori da verificare su Commons)
SAP.scenari.unshift({
 id: "racconto-pess", scen: "pess", futuro: true, title: "Racconto: la tempesta perfetta", sub: "Scenario pessimistico: emissioni alte e punti di non ritorno",
 from: 0, to: -1, unit: "anni", color: "#e63946",
 dom: [0, -0.000024, -0.000074, -0.000274, -0.01, -0.1, -1], rng: [0, .2, .45, .62, .78, .9, 1],
 intro: "Che cosa succederebbe se le emissioni continuassero a crescere per gran parte del secolo? È lo scenario «caso peggiore» dell'IPCC (SSP5-8.5): oggi è considerato poco probabile, ma serve a capire che cosa rischiamo. Il riscaldamento supera i 4 °C nel 2100 e si superano diversi punti di non ritorno. Segui il racconto: il globo ti porta nei luoghi dove le cose cambiano più in fretta.",
 steps: [
  {t: 0, title: "2026: il bivio", view: [10, 30, 1.1], certezza: "alta",
   img: {file: "File:Keeling Curve full record.png", author: "Scripps Institution of Oceanography", lic: "CC BY-SA 4.0", cap: "La CO₂ nell'aria misurata a Mauna Loa dal 1958", tipo: "grafico"},
   text: "In questo scenario il mondo non riduce le emissioni: si continua a bruciare carbone, petrolio e gas, e le foreste tropicali vengono tagliate. Nel 2100 il riscaldamento arriva a circa 4,4 °C (tra 3,3 e 5,7 °C) rispetto all'Ottocento.",
   oggi: "Alla COP28 (2023) i paesi hanno deciso di «allontanarsi dai combustibili fossili»; questo scenario descrive che cosa succede se l'impegno non viene mantenuto.",
   curiosita: "Lo scenario SSP5-8.5 si chiama «sviluppo alimentato dai fossili»: immagina un mondo ricco che cresce in fretta usando soprattutto carbone.",
   fonti: ["IPCC AR6 WGI, SPM", "Hausfather & Peters 2020, Nature"]},
  {t: -0.000004, title: "2030: la vaquita è la prima a sparire", view: [-114.6, 31.1, 5.5], certezza: "media", extinct: ["vaquita"],
   img: {file: "File:Vaquita6 Olson NOAA.jpg", author: "Paula Olson, NOAA", lic: "Pubblico dominio", cap: "Vaquite fotografate nel Golfo di California (NOAA)", tipo: "foto"},
   text: "Senza controlli sulla pesca illegale, le ultime vaquite muoiono nelle reti già entro il 2030. È il primo segnale: le specie già ridotte a pochissimi individui non hanno più margine.",
   oggi: "La vaquita è «in pericolo critico» per la IUCN; il Messico ha vietato le reti da posta nel suo ultimo rifugio.",
   curiosita: "Fu scoperta dagli scienziati solo nel 1958, grazie a tre crani trovati su una spiaggia.",
   fonti: ["IUCN Red List: Phocoena sinus (CR)"]},
  {t: -0.000008, title: "Il Mediterraneo bolle", view: [6, 40, 3], certezza: "alta", species: ["posidonia", "pinna-nobilis"],
   img: {file: "File:Intense marine heatwave hits the western Mediterranean Sea (Copernicus 2025-06-25).png", author: "Unione Europea, Copernicus Marine Service", lic: "Attribuzione", cap: "Ondata di calore marina nel Mediterraneo occidentale, giugno 2025 (Copernicus)", tipo: "mappa"},
   text: "Le ondate di calore marine diventano la normalità: per settimane l'acqua resta sopra i 28–30 °C. Gorgonie, spugne e praterie di Posidonia muoiono a chilometri di distanza. Meduse e specie tropicali prendono il loro posto.",
   oggi: "Il programma europeo Copernicus misura ogni giorno la temperatura del mare dallo spazio e segnala le ondate di calore marine.",
   curiosita: "Il Mediterraneo si scalda circa il 20% più in fretta della media degli oceani del mondo.",
   fonti: ["Garrabou et al. 2022, Global Change Biology", "Copernicus Marine Service"]},
  {t: -0.000013, title: "Addio alla nacchera di mare", view: [17.9, 40.7, 5.5], certezza: "media", extinct: ["pinna-nobilis"],
   img: {file: "File:Pinna nobilis - Torre Guaceto.jpg", author: "Ferdinando Traversa", lic: "CC BY-SA 4.0", cap: "Pinna nobilis nella riserva di Torre Guaceto (Puglia)", tipo: "foto"},
   text: "Il parassita che dal 2016 uccide le nacchere si diffonde con l'acqua calda fino nelle ultime lagune. Verso il 2040 il più grande bivalve del Mediterraneo scompare.",
   oggi: "In Italia e in Spagna si allevano gli ultimi esemplari resistenti per salvarli.",
   curiosita: "Una nacchera può superare un metro di lunghezza e vivere più di 40 anni.",
   fonti: ["Vázquez-Luis et al. 2017", "IUCN Red List: Pinna nobilis (CR)"]},
  {t: -0.000014, title: "Le barriere dei Caraibi crollano", view: [-80.6, 25, 4.5], certezza: "media", extinct: ["corallo-corno-alce", "corallo-corno-cervo"],
   img: {file: "File:Acropora palmata 02 Pickles Reef 20230713.jpg", author: "Jstuby", lic: "CC0", cap: "Corallo corna d'alce sbiancato, Florida Keys, luglio 2023", tipo: "foto"},
   text: "Ondate di calore sempre più lunghe uccidono i coralli più velocemente di quanto possano ricrescere. Entro il 2040 i grandi coralli corna d'alce e corna di cervo spariscono; le barriere diventano scogli coperti di alghe.",
   oggi: "Il Global Tipping Points Report 2025 considera già superato il punto di non ritorno delle barriere coralline tropicali.",
   curiosita: "Una barriera corallina copre meno dell'1% del fondo del mare ma ospita circa un quarto di tutte le specie marine.",
   fonti: ["Lenton et al., Global Tipping Points Report 2025", "IPCC AR6 WGII"]},
  {t: -0.000015, title: "L'ultimo rinoceronte di Sumatra", view: [105.8, -4.9, 5], certezza: "media", extinct: ["rinoceronte-sumatra"],
   img: {file: "File:Sumatran Rhino 2.jpg", author: "Charles W. Hardin", lic: "CC BY 2.0", cap: "Rinoceronte di Sumatra", tipo: "foto"},
   text: "Incendi e disboscamento riducono le ultime foreste. Senza nuove nascite in cattività, gli ultimi rinoceronti di Sumatra muoiono verso il 2040: scompare il parente vivente del rinoceronte lanoso.",
   oggi: "L'IUCN lo considera «in pericolo critico»; ne restano poche decine.",
   curiosita: "È l'unico rinoceronte asiatico con due corni ed è capace di nuotare nei fiumi.",
   fonti: ["IUCN Red List: Dicerorhinus sumatrensis (CR)"]},
  {t: -0.000018, title: "Il permafrost si scioglie", view: [134.8, 67.6, 5.5], certezza: "alta",
   img: {file: "File:Batagaika crater NASA.jpg", author: "NASA Earth Observatory", lic: "Pubblico dominio", cap: "Il cratere di Batagaika in Siberia visto dal satellite (NASA)", tipo: "foto"},
   text: "Il suolo ghiacciato dell'Artico, il permafrost, si scioglie e sprofonda. In Siberia il cratere di Batagaika, lungo più di un chilometro, si allarga ogni anno. Il terreno che si scongela libera CO₂ e metano, che scaldano ancora di più il pianeta.",
   oggi: "Il permafrost contiene circa il doppio del carbonio che c'è oggi nell'aria: l'IPCC lo considera una delle retroazioni più importanti.",
   curiosita: "Gli abitanti lo chiamano «la porta dell'inferno»: dalle sue pareti escono ossa di mammut e di cavalli dell'era glaciale.",
   fonti: ["Schuur et al. 2015, Nature", "IPCC AR6 WGI"]},
  {t: -0.000024, title: "2050: niente più rinoceronti di Giava", view: [105.4, -6.8, 6], certezza: "media", extinct: ["rinoceronte-giava"],
   text: "Tutti i rinoceronti di Giava vivono in un solo parco, Ujung Kulon, ai piedi del vulcano Krakatoa. Bracconaggio, malattie o uno tsunami bastano a cancellarli: in questo scenario scompaiono verso il 2050.",
   oggi: "Il parco nazionale di Ujung Kulon è patrimonio dell'umanità UNESCO dal 1991.",
   curiosita: "L'ultimo rinoceronte di Giava del Vietnam fu ucciso dai bracconieri nel 2010.",
   fonti: ["IUCN Red List: Rhinoceros sondaicus (CR)", "WWF Vietnam 2011"]},
  {t: -0.000034, title: "2060: la scimmia scoperta troppo tardi", view: [99, 1.6, 5], certezza: "media", extinct: ["orango-tapanuli"],
   img: {file: "File:Pongo tapanuliensis female.jpg", author: "Tim Laman", lic: "CC BY 4.0", cap: "Femmina di orango di Tapanuli", tipo: "foto"},
   text: "L'orango di Tapanuli, descritto nel 2017, vive in una sola foresta. Strade, miniere e una centrale idroelettrica la dividono in pezzi troppo piccoli. Verso il 2060 la specie si estingue: era la grande scimmia più rara del mondo.",
   oggi: "Il quadro di Kunming-Montréal chiede di fermare le estinzioni causate dall'uomo entro il 2030.",
   curiosita: "Da quando è stato scoperto, nel 2017, è stato una specie «nuova» per meno di mezzo secolo.",
   fonti: ["Nater et al. 2017, Current Biology", "IUCN Red List: Pongo tapanuliensis (CR)"]},
  {t: -0.000045, title: "L'Amazzonia diventa savana?", view: [-60, -6, 3], certezza: "bassa",
   img: {file: "File:Deforestation in the Amazon (46200453914).jpg", author: "Sentinel Hub", lic: "CC BY 2.0", cap: "Deforestazione in Amazzonia vista dall'alto", tipo: "foto"},
   text: "Siccità, incendi e disboscamento potrebbero spingere parte dell'Amazzonia oltre una soglia: la foresta non riesce più a produrre la propria pioggia e si trasforma in savana. Quando e se succederà è molto discusso, ma il rischio cresce con il caldo.",
   oggi: "Al vertice di Belém (2023) gli otto paesi amazzonici si sono impegnati a fermare la deforestazione illegale entro il 2030.",
   curiosita: "Gli alberi dell'Amazzonia «sudano» così tanta acqua che sopra la foresta scorrono «fiumi volanti» di vapore.",
   fonti: ["Flores et al. 2024, Nature", "Armstrong McKay et al. 2022, Science"]},
  {t: -0.00005, title: "Troppo caldo per vivere all'aperto", view: [51.5, 26, 4], certezza: "media",
   text: "Nel Golfo Persico l'aria diventa così calda e umida che per alcune ore il corpo umano non riesce più a raffreddarsi sudando. In quei giorni si può stare all'aperto solo per poco: le città vivono di notte e sotto l'aria condizionata.",
   oggi: "L'Organizzazione mondiale della sanità considera il caldo estremo una delle principali minacce alla salute legate al clima.",
   curiosita: "Il limite si misura con la «temperatura di bulbo umido»: un termometro avvolto in un panno bagnato. Oltre circa 35 °C anche una persona sana in ombra rischia la vita.",
   fonti: ["Pal & Eltahir 2016, Nature Climate Change", "Vecellio et al. 2022, Journal of Applied Physiology"]},
  {t: -0.000054, title: "La balena franca nordatlantica", view: [-66, 43, 3.5], certezza: "media", extinct: ["balena-franca-nordatlantica"],
   img: {file: "File:Eubalaena glacialis with calf.jpg", author: "NOAA", lic: "Pubblico dominio", cap: "Balena franca nordatlantica con il piccolo", tipo: "foto"},
   text: "Con il mare più caldo il suo cibo si sposta verso nord, in rotte piene di navi e di corde da pesca. Nascono sempre meno piccoli: verso il 2080 la specie scompare.",
   oggi: "Stati Uniti e Canada impongono limiti di velocità alle navi nelle zone delle balene.",
   curiosita: "Ogni balena franca ha sul capo callosità bianche diverse da tutte le altre: i ricercatori le riconoscono come impronte digitali.",
   fonti: ["NOAA Fisheries 2024", "Meyer-Gutbrod et al. 2021, Oceanography"]},
  {t: -0.00006, title: "Venezia sommersa", view: [12.33, 45.43, 6.5], certezza: "media",
   img: {file: "File:Acqua alta in Piazza San Marco.jpg", author: "Wolfgang Moroder", lic: "CC BY-SA 3.0", cap: "Acqua alta in Piazza San Marco", tipo: "foto"},
   text: "Con il mare quasi un metro più alto, il MOSE dovrebbe restare chiuso quasi sempre e la laguna morirebbe senza ricambio d'acqua. In questo scenario Venezia vive sommersa per buona parte dell'anno e molti abitanti se ne vanno.",
   oggi: "Il MOSE funziona dal 2020 ed è stato progettato per proteggere la città da maree fino a circa 3 metri.",
   curiosita: "L'«acqua granda» del 4 novembre 1966 arrivò a 194 cm: fu l'inondazione più alta mai misurata a Venezia.",
   fonti: ["IPCC AR6 WGI, capitolo 9", "Lionello et al. 2021, Natural Hazards and Earth System Sciences"]},
  {t: -0.000073, title: "2100: i pinguini imperatore", view: [-26.5, -75.6, 4], certezza: "media", extinct: ["pinguino-imperatore"],
   img: {file: "File:Halley Emperor Penguin Colony in 1999.jpg", author: "Mtpaley", lic: "CC BY-SA 4.0", cap: "La colonia di pinguini imperatore di Halley Bay (Antartide)", tipo: "foto"},
   text: "I pinguini imperatore allevano i piccoli sul ghiaccio marino attaccato alla costa. Se si rompe troppo presto, i pulcini, ancora senza piume impermeabili, annegano. Con emissioni alte quasi tutte le colonie scompaiono entro il 2100.",
   oggi: "Ad aprile 2026 la IUCN ha spostato il pinguino imperatore tra le specie «in pericolo».",
   curiosita: "Tra il 2016 e il 2018 la colonia di Halley Bay, una delle più grandi, perse quasi tutti i pulcini perché il ghiaccio si ruppe in anticipo.",
   fonti: ["Jenouvrier et al. 2021, Global Change Biology", "Fretwell & Trathan 2019, Antarctic Science"]},
  {t: -0.000074, title: "2100: le praterie di Posidonia", view: [12.3, 38, 5.5], certezza: "media", extinct: ["posidonia"],
   img: {file: "File:Praterie di Posidonia oceanica.jpg", author: "Albarubescens", lic: "CC BY-SA 4.0", cap: "Prateria di Posidonia oceanica", tipo: "foto"},
   text: "La Posidonia è una pianta, non un'alga: forma praterie sottomarine che proteggono le spiagge e sono asili per i pesci. Con il mare troppo caldo le praterie muoiono: nel caso peggiore la specie rischia l'estinzione funzionale entro il 2100.",
   oggi: "La Posidonia è protetta dalla direttiva europea Habitat (1992) e il suo taglio è vietato.",
   curiosita: "Una prateria di Posidonia vicino a Formentera è forse uno degli organismi più antichi della Terra: alcuni studi le danno decine di migliaia di anni.",
   fonti: ["Chefaoui et al. 2018, Global Change Biology", "Arnaud-Haond et al. 2012, PLoS ONE"]},
  {t: -0.000094, title: "La fine dell'orso polare", view: [-85, 74, 2.8], certezza: "media", extinct: ["orso-polare"], species: ["fut-pizzly"],
   img: {file: "File:Polar bear on sea ice (52791040875).jpg", author: "USFWS Alaska", lic: "Pubblico dominio", cap: "Orso polare sul ghiaccio marino", tipo: "foto"},
   text: "Senza ghiaccio marino per gran parte dell'anno gli orsi polari non riescono più a cacciare le foche. Con emissioni alte quasi tutte le popolazioni crollano entro il 2100, le ultime verso il 2120. Restano gli ibridi con l'orso bruno, i «pizzly».",
   oggi: "L'accordo internazionale sull'orso polare (1973) unisce i cinque paesi dove vive.",
   curiosita: "Un orso polare sente l'odore di una foca a più di un chilometro di distanza, anche sotto la neve.",
   fonti: ["Molnár et al. 2020, Nature Climate Change"]},
  {t: -0.000124, title: "Le perdite dell'Italia", view: [13.8, 41.8, 5], certezza: "bassa", extinct: ["orso-marsicano", "abete-nebrodi", "foca-monaca", "anguilla-europea"],
   img: {file: "File:Orso bruno marsicano.jpg", author: "Marco Tersigni", lic: "CC BY 2.0", cap: "Orso bruno marsicano", tipo: "foto"},
   text: "Verso il 2150 l'Italia perde alcune delle sue specie simbolo. L'orso marsicano, rimasto con una cinquantina di esemplari, non regge siccità e isolamento; l'abete dei Nebrodi, con una trentina di alberi selvatici, muore di caldo; la foca monaca non trova più grotte tranquille; l'anguilla europea, se la corrente atlantica collassa, non trova più la strada dal Mar dei Sargassi.",
   oggi: "Il Parco Nazionale d'Abruzzo, Lazio e Molise protegge l'orso marsicano dal 1923; l'abete dei Nebrodi si moltiplica nei vivai delle Madonie.",
   curiosita: "Le anguille europee nascono tutte nel Mar dei Sargassi, a più di 5000 km dall'Italia: lo scoprì il danese Johannes Schmidt negli anni Venti.",
   fonti: ["Ciucci et al. 2017, Ursus", "IUCN Red List", "Jacoby et al. 2015"]},
  {t: -0.000174, title: "La salamandra del Monviso", view: [7.1, 44.7, 6], certezza: "bassa", extinct: ["salamandra-lanza"],
   img: {file: "File:Salamandra lanzai (Franco Andreone).jpeg", author: "Franco Andreone", lic: "CC BY-SA 2.5", cap: "Salamandra di Lanza", tipo: "foto"},
   text: "La salamandra di Lanza vive solo in poche valli attorno al Monviso. Ama il fresco e l'umido: con estati sempre più calde e secche il suo piccolo mondo si restringe finché, verso il 2200, scompare.",
   oggi: "È protetta dalla direttiva europea Habitat ed è oggetto di monitoraggio nel Parco del Monviso.",
   curiosita: "Partorisce piccoli già formati, senza passare dallo stadio di girino: un adattamento alla montagna senza pozze d'acqua.",
   fonti: ["Andreone et al., studi sulla salamandra di Lanza"]},
  {t: -0.000274, title: "2300: il ghiacciaio dell'apocalisse", view: [-106, -75, 3], certezza: "bassa",
   img: {file: "File:Thwaites Glacier.jpg", author: "NASA", lic: "Pubblico dominio", cap: "Il ghiacciaio Thwaites in Antartide occidentale", tipo: "foto"},
   text: "Il ghiacciaio Thwaites è grande quanto la Gran Bretagna e tiene a freno la calotta dell'Antartide occidentale. Se cedesse, nel caso peggiore il mare potrebbe salire di molti metri entro il 2300. È poco probabile, ma non si può escludere.",
   oggi: "Dal 2018 la collaborazione internazionale sul ghiacciaio Thwaites (ITGC) lo studia con robot sottomarini.",
   curiosita: "I giornali lo chiamano «il ghiacciaio dell'apocalisse», ma i glaciologi preferiscono il suo nome vero.",
   fonti: ["IPCC AR6 WGI, capitolo 9", "Scambos et al. 2017, Global and Planetary Change"]},
  {t: -0.000474, title: "La sesta estinzione di massa", view: [20, 0, 1], certezza: "bassa",
   img: {file: "File:Extinction Intensity.png", author: "Dragons flight", lic: "CC BY-SA 3.0", cap: "Le grandi estinzioni del passato nei fossili", tipo: "grafico"},
   text: "Se si perdessero tutte le specie oggi minacciate e il ritmo continuasse, in alcuni secoli si raggiungerebbe una vera estinzione di massa: la sesta della storia della Terra, la prima causata da una sola specie.",
   oggi: "L'IPBES (2019) stima che circa un milione di specie animali e vegetali sia a rischio di estinzione.",
   curiosita: "Le cinque grandi estinzioni del passato hanno cancellato ciascuna almeno tre specie su quattro.",
   fonti: ["Barnosky et al. 2011, Nature", "IPBES Global Assessment 2019"]},
  {t: -0.002, title: "Dove gli umani se ne vanno", view: [30.1, 51.4, 5], certezza: "media", species: ["fut-ratto", "lupo"],
   text: "Nei luoghi abbandonati, la natura torna. Nella zona di Chernobyl, evacuata nel 1986, oggi vivono lupi, alci e cavalli di Przewalski. Nelle città lasciate dal mare che sale e dal caldo, a prosperare sono le specie adattabili: ratti, piccioni, gabbiani.",
   oggi: "La zona di esclusione di Chernobyl è diventata in parte una riserva naturale (2016).",
   curiosita: "Nella zona di Chernobyl ci sono più lupi che nelle riserve vicine dove gli uomini vivono.",
   fonti: ["Deryabina et al. 2015, Current Biology"]},
  {t: -0.01, title: "Il mare entra nella Pianura Padana", view: [11.5, 45, 4], certezza: "bassa",
   text: "In diecimila anni, con emissioni altissime, le calotte di Groenlandia e Antartide occidentale possono sciogliersi in gran parte: il mare sale di decine di metri. L'Adriatico entra nella Pianura Padana fino a Ferrara e oltre.",
   oggi: "L'IPCC calcola che con 5 °C di riscaldamento il mare potrebbe salire di 19–22 metri in 2000 anni.",
   curiosita: "Durante il Pliocene, tre milioni di anni fa, con una CO₂ simile a quella di oggi, il mare era circa 20 metri più alto.",
   fonti: ["IPCC AR6 WGI", "Clark et al. 2016, Nature Climate Change"]},
  {t: -0.1, title: "Una nuova radiazione della vita", view: [140, 0, 1.4], certezza: "ipotesi", species: ["fut-cervo-nano", "fut-ratto"],
   text: "Dopo ogni estinzione di massa i sopravvissuti si diversificano e occupano i posti rimasti liberi. Su isole e in ambienti isolati nascono nuove forme: piccoli cervi nani, roditori più grandi, uccelli che perdono il volo. Ci vogliono centinaia di migliaia o milioni di anni.",
   oggi: "Proteggere oggi le isole e le specie endemiche significa conservare il materiale da cui ripartirà l'evoluzione.",
   curiosita: "In Sicilia vivevano elefanti nani alti meno di un metro: si erano evoluti da elefanti giganti arrivati sull'isola.",
   fonti: ["Barnosky et al. 2011, Nature", "Lomolino 2005, Journal of Biogeography"]},
  {t: -0.65, title: "La glaciazione che non arriva", view: [-85, 60, 1.5], certezza: "media",
   img: {file: "File:Northern icesheet hg.png", author: "Hannes Grobe/AWI", lic: "CC BY 2.5", cap: "Le calotte dell'ultima glaciazione nell'emisfero nord", tipo: "mappa"},
   text: "Con 3000 o più miliardi di tonnellate di carbonio emesse, la prossima glaciazione è rimandata di oltre mezzo milione di anni. Le nostre emissioni di pochi secoli cambiano il clima della Terra per un tempo più lungo di tutta la storia di Homo sapiens.",
   oggi: "Talento e Ganopolski (2021) hanno calcolato come le emissioni umane spostano i prossimi cicli glaciali.",
   curiosita: "Homo sapiens esiste da circa 300 000 anni: in questo scenario la prossima era glaciale arriverebbe fra un tempo più lungo del doppio.",
   fonti: ["Talento & Ganopolski 2021, Earth System Dynamics"]},
  {t: -1, title: "Un milione di anni", view: [20, 10, 1], certezza: "ipotesi", species: ["fut-sapiens-terra"],
   text: "La Terra si è ripresa: nuove specie riempiono foreste, mari e isole. Se Homo sapiens c'è ancora, vive in un mondo che porta per sempre il segno di pochi secoli di storia umana, come uno strato sottile nelle rocce.",
   oggi: "L'articolo 9 della Costituzione italiana tutela l'ambiente «anche nell'interesse delle future generazioni».",
   curiosita: "Fra milioni di anni i geologi del futuro potrebbero riconoscere il nostro tempo da uno strato con plastica, cemento e isotopi delle bombe atomiche.",
   fonti: ["Barnosky et al. 2011, Nature", "Zalasiewicz et al. 2016, Anthropocene"]}
 ],
 markers: [
  {lat: 31.0, lon: -114.5, label: "Rifugio della vaquita", kind: "evento", from: 0, to: -0.000006, taxon: "vaquita", text: "Alto Golfo di California."},
  {lat: 67.58, lon: 134.77, label: "Cratere di Batagaika", kind: "sito", from: -0.000015, to: -0.000022, text: "Il cratere da permafrost più grande del mondo."},
  {lat: -6.75, lon: 105.35, label: "Ujung Kulon", kind: "sito", from: -0.00002, to: -0.000028, taxon: "rinoceronte-giava", text: "L'unico parco dove vive il rinoceronte di Giava."},
  {lat: 45.43, lon: 12.33, label: "Venezia", kind: "sito", from: -0.000055, to: -0.000066, text: "La città sulla laguna."},
  {lat: -75.58, lon: -26.5, label: "Halley Bay", kind: "sito", from: -0.00007, to: -0.000076, taxon: "pinguino-imperatore", text: "Una delle più grandi colonie di pinguini imperatore."},
  {lat: 51.39, lon: 30.1, label: "Chernobyl", kind: "sito", from: -0.0015, to: -0.003, text: "La zona di esclusione, oggi rifugio di animali selvatici."}
 ]});
// RACCONTO GUIDATO — scenario ottimistico (bozza del 29/10/2026: immagini e autori da verificare su Commons)
SAP.scenari.unshift({
 id: "racconto-ott", scen: "ott", futuro: true, title: "Racconto: la grande riparazione", sub: "Scenario ottimistico: zero emissioni nette verso il 2050–2070",
 from: 0, to: -1, unit: "anni", color: "#2a9d8f",
 dom: [0, -0.000024, -0.000074, -0.000274, -0.01, -0.1, -1], rng: [0, .2, .45, .62, .78, .9, 1],
 intro: "E se ce la facessimo? In questo scenario il mondo riduce in fretta le emissioni, protegge il 30% di terre e mari e usa scienza e tecnologia per riparare la natura. Il riscaldamento supera di poco 1,5 °C e poi scende. Non tutto si salva: alcune perdite sono già inevitabili. Ma la storia è quella di una specie che impara a curare il proprio pianeta.",
 steps: [
  {t: 0, title: "2026: la svolta", view: [10, 30, 1.1], certezza: "alta",
   img: {file: "File:Keeling Curve full record.png", author: "Scripps Institution of Oceanography", lic: "CC BY-SA 4.0", cap: "La CO₂ nell'aria misurata a Mauna Loa dal 1958", tipo: "grafico"},
   text: "La CO₂ nell'aria è la più alta da milioni di anni, ma le energie rinnovabili crescono più in fretta di ogni previsione: sole e vento sono già oggi le fonti di elettricità più economiche in gran parte del mondo. In questo scenario la curva della CO₂ smette di salire entro pochi anni.",
   oggi: "Alla COP28 (2023) quasi 200 paesi si sono impegnati a triplicare le rinnovabili entro il 2030.",
   curiosita: "Negli ultimi anni il solare è la fonte di elettricità che cresce più in fretta nel mondo.",
   fonti: ["IEA Renewables 2024", "IPCC AR6 WGIII"]},
  {t: -0.000005, title: "La vaquita si salva per un pelo", view: [-114.6, 31.1, 5.5], certezza: "bassa", species: ["vaquita"],
   img: {file: "File:Vaquita6 Olson NOAA.jpg", author: "Paula Olson, NOAA", lic: "Pubblico dominio", cap: "Vaquite fotografate nel Golfo di California (NOAA)", tipo: "foto"},
   text: "Restano meno di dieci vaquite, ma le femmine continuano a fare piccoli sani. Se le reti spariscono davvero dal loro rifugio, la popolazione può risalire lentamente: è già successo con altre specie ridotte a pochissimi individui.",
   oggi: "Nella zona di tolleranza zero del Golfo di California le reti da posta sono vietate e controllate anche con i droni.",
   curiosita: "Gli studi genetici mostrano che la vaquita ha sempre avuto una popolazione piccola: per questo soffre poco la consanguineità e può ancora riprendersi.",
   fonti: ["Robinson et al. 2022, Science", "IUCN Red List: Phocoena sinus (CR)"]},
  {t: -0.000006, title: "Rinoceronti bianchi del nord in provetta", view: [36.9, 0.0, 5.5], certezza: "media", species: ["rinoceronte-bianco"],
   img: {file: "File:Najin and Fatu.jpg", author: "Schau99", lic: "CC BY-SA 4.0", cap: "Najin e Fatu, gli ultimi due rinoceronti bianchi settentrionali (Ol Pejeta, Kenya)", tipo: "foto"},
   text: "Del rinoceronte bianco settentrionale restano solo due femmine, Najin e Fatu. Gli scienziati del progetto BioRescue hanno prodotto embrioni in laboratorio con i loro ovociti e il seme congelato di maschi morti. In questo scenario nascono i primi piccoli da madri «in affitto» di rinoceronte bianco meridionale.",
   oggi: "Nel 2024 BioRescue ha annunciato la prima gravidanza di rinoceronte ottenuta con la fecondazione in vitro.",
   curiosita: "Najin e Fatu sono madre e figlia e sono sorvegliate giorno e notte da guardie armate.",
   fonti: ["Hildebrandt et al., BioRescue 2024", "IUCN SSC African Rhino Specialist Group"]},
  {t: -0.000008, title: "La lince iberica torna", view: [-4, 38.3, 5], certezza: "alta", species: ["lince-iberica"],
   img: {file: "File:Lince ibérico (Lynx pardinus), Almuradiel, Ciudad Real, España, 2021-12-19, DD 07.jpg", author: "Diego Delso", lic: "CC BY-SA 4.0", cap: "Lince iberica in Sierra Morena (Spagna)", tipo: "foto"},
   text: "Nel 2002 restavano meno di cento linci iberiche. Grazie ad allevamenti, reintroduzioni e alla protezione dei conigli selvatici, nel 2024 erano più di duemila. È una delle storie di salvataggio più belle d'Europa e mostra che si può tornare indietro.",
   oggi: "Nel 2024 la IUCN ha spostato la lince iberica da «in pericolo» a «vulnerabile», grazie al progetto europeo LIFE.",
   curiosita: "La lince iberica mangia quasi solo conigli: per salvarla bisognava prima salvare loro, colpiti da due malattie virali.",
   fonti: ["IUCN Red List 2024: Lynx pardinus (VU)", "Progetto LIFE Lynxconnect"]},
  {t: -0.000012, title: "Coralli più resistenti al caldo", view: [146.5, -18.3, 4], certezza: "media", species: ["fut-corallo-resistente"],
   img: {file: "File:FKNMS - coral nursery (27367671414).jpg", author: "NOAA National Marine Sanctuaries", lic: "Pubblico dominio", cap: "Un vivaio di coralli nelle Florida Keys", tipo: "foto"},
   text: "Anche nello scenario migliore le barriere perdono gran parte dei coralli. Ma nei vivai si selezionano coralli che sopportano meglio il caldo, e si ripiantano sulle barriere. È l'«evoluzione assistita»: aiutare la natura a fare in fretta quello che farebbe in migliaia di anni.",
   oggi: "In Australia il programma di ripristino della Grande Barriera (RRAP) sperimenta coralli tolleranti al calore.",
   curiosita: "Alcuni coralli del Mar Rosso resistono a temperature che ucciderebbero quelli di altri mari: sono studiati come «super coralli».",
   fonti: ["van Oppen et al. 2015, PNAS", "Fine et al. 2013, Global Change Biology"]},
  {t: -0.000014, title: "La Marmolada si perde comunque", view: [11.86, 46.43, 6], certezza: "alta",
   img: {file: "File:Marmolada glacier.jpg", author: "autore non indicato", lic: "Pubblico dominio", cap: "Il ghiacciaio della Marmolada", tipo: "foto"},
   text: "Alcune perdite sono già scritte: il ghiacciaio della Marmolada sparirà quasi del tutto anche se smettessimo oggi di emettere CO₂, perché il caldo accumulato basta a scioglierlo. Ma con poco riscaldamento si salvano i ghiacciai più alti delle Alpi.",
   oggi: "Uno studio del 2023 (Rounce et al.) calcola che con 1,5 °C si salverebbe circa metà dei ghiacciai del mondo.",
   curiosita: "Dal 2019 in Islanda c'è una targa per il ghiacciaio Okjökull, il primo dichiarato «morto»: è indirizzata «a chi verrà dopo di noi».",
   fonti: ["Rounce et al. 2023, Science", "Comitato Glaciologico Italiano"]},
  {t: -0.000016, title: "Zanzare contro la malaria?", view: [-1.5, 12.4, 5], certezza: "ipotesi",
   img: {file: "File:Anopheles gambiae mosquito feeding (CDC PHIL 1354).jpg", author: "CDC / James Gathany", lic: "Pubblico dominio", cap: "Zanzara Anopheles gambiae, che trasmette la malaria (CDC)", tipo: "foto"},
   text: "La malaria uccide ogni anno più di mezzo milione di persone, quasi tutte bambini africani. Il «gene drive» è un pezzo di DNA che si diffonde da solo nelle zanzare e può renderle sterili o incapaci di trasmettere il parassita. È potentissimo e discusso: se funzionasse, potrebbe salvare milioni di vite, ma cambierebbe un ecosistema per sempre.",
   oggi: "Nel 2025 il Burkina Faso ha sospeso il progetto Target Malaria; l'Organizzazione mondiale della sanità ha pubblicato linee guida per sperimentarlo con prudenza.",
   curiosita: "Delle circa 3500 specie di zanzare, solo poche decine trasmettono la malaria all'uomo.",
   fonti: ["WHO World Malaria Report 2024", "Hammond et al. 2016, Nature Biotechnology"]},
  {t: -0.000024, title: "2050: zero emissioni nette", view: [10, 50, 1.3], certezza: "media",
   text: "Verso il 2050 l'Europa e molti altri paesi emettono solo quanta CO₂ riescono a togliere dall'aria con foreste, suoli e tecnologie. Il riscaldamento si ferma poco sopra 1,5 °C e comincia a scendere. Aria più pulita, città più silenziose: anche la salute migliora.",
   oggi: "La legge europea sul clima (2021) obbliga l'UE alla neutralità climatica entro il 2050; nel 2026 è stato fissato l'obiettivo del −90% per il 2040.",
   curiosita: "L'inquinamento dell'aria da combustibili fossili causa ogni anno milioni di morti premature: ridurre la CO₂ salva vite anche per questo.",
   fonti: ["IPCC AR6 WGIII", "Regolamento UE 2021/1119"]},
  {t: -0.00003, title: "Le città diventano foreste", view: [9.19, 45.49, 7], certezza: "media", species: ["fut-trifoglio-urbano"],
   img: {file: "File:Il Bosco Verticale Milano Px (137734459).jpeg", author: "Jeronimo Alcala", lic: "CC BY 3.0", cap: "Il Bosco Verticale a Milano", tipo: "foto"},
   text: "Le città si riempiono di alberi, tetti verdi e corridoi per gli animali, che abbassano la temperatura nei giorni di caldo. Intanto l'evoluzione lavora anche in città: piante e animali urbani cambiano in pochi decenni per adattarsi al nuovo ambiente.",
   oggi: "La legge europea sul ripristino della natura (2024) vieta di ridurre il verde urbano e chiede di aumentarlo.",
   curiosita: "Uno studio in 160 città del mondo ha scoperto che il trifoglio bianco, in città, perde la capacità di produrre cianuro: è evoluzione «sotto casa».",
   fonti: ["Santangelo et al. 2022, Science", "Regolamento UE 2024/1991"]},
  {t: -0.00004, title: "La nacchera di mare torna", view: [17.9, 40.7, 5.5], certezza: "bassa", species: ["pinna-nobilis"],
   img: {file: "File:Pinna nobilis - Torre Guaceto.jpg", author: "Ferdinando Traversa", lic: "CC BY-SA 4.0", cap: "Pinna nobilis a Torre Guaceto (Puglia)", tipo: "foto"},
   text: "Alcune nacchere sono sopravvissute al parassita: forse sono resistenti. Allevate e riportate in mare, fanno ripartire la specie. Con un Mediterraneo che smette di scaldarsi, le praterie dove vive tornano a crescere.",
   oggi: "Progetti di allevamento in Italia e Spagna cercano esemplari resistenti per salvare la specie.",
   curiosita: "Le nacchere filtrano l'acqua: una sola ne pulisce diversi litri ogni ora.",
   fonti: ["Vázquez-Luis et al. 2017", "IUCN Red List: Pinna nobilis (CR)"]},
  {t: -0.00005, title: "La foresta atlantica e il tamarino leone dorato", view: [-42.3, -22.5, 5.5], certezza: "alta",
   img: {file: "File:Golden lion tamarin family.jpg", author: "Steve, Washington DC", lic: "CC BY-SA 2.0", cap: "Famiglia di tamarini leone dorati", tipo: "foto"},
   text: "Negli anni Settanta restavano circa duecento tamarini leone dorati. Corridoi di foresta ripiantata hanno riunito le popolazioni e oggi sono migliaia. In questo scenario la Foresta Atlantica del Brasile, ridotta a pezzi, torna a essere un tutt'uno.",
   oggi: "Il Patto per il ripristino della Foresta Atlantica punta a ripristinare 15 milioni di ettari entro il 2050.",
   curiosita: "Dopo l'epidemia di febbre gialla del 2016–2018, che ne uccise circa un terzo, gli scienziati hanno vaccinato i tamarini selvatici uno per uno.",
   fonti: ["Associação Mico-Leão-Dourado", "IUCN Red List: Leontopithecus rosalia (EN)"]},
  {t: -0.000074, title: "2100: Venezia si difende", view: [12.33, 45.43, 6.5], certezza: "media",
   img: {file: "File:03 movimento paratoie.jpg", author: "Consorzio Venezia Nuova", lic: "CC BY-SA 3.0", cap: "Le paratoie del MOSE si alzano", tipo: "foto"},
   text: "Nel 2100 la Terra è circa 1,4–1,8 °C più calda dell'Ottocento e il mare è salito di 30–60 cm. Il MOSE si chiude più spesso di oggi ma riesce ancora a proteggere Venezia. Le specie spostate dal caldo trovano spazio nelle aree protette collegate tra loro.",
   oggi: "Il MOSE funziona dal 2020; l'Italia ha un Piano nazionale di adattamento ai cambiamenti climatici dal 2023.",
   curiosita: "Venezia è costruita su milioni di pali di legno piantati nel fango della laguna, alcuni da più di mille anni.",
   fonti: ["IPCC AR6 WGI, SPM"]},
  {t: -0.000124, title: "Le barriere coralline rinascono", view: [146.5, -18.3, 3.5], certezza: "bassa", species: ["fut-corallo-resistente", "tartaruga-verde"],
   img: {file: "File:Blue Linckia Starfish.JPG", author: "Richard Ling", lic: "CC BY-SA 3.0", cap: "Una barriera corallina sana con una stella marina blu", tipo: "foto"},
   text: "Con la temperatura che scende lentamente, i coralli sopravvissuti e quelli ripiantati ricostruiscono le barriere. Non sono le stesse di prima: ci sono specie più resistenti e meno varietà. Ma pesci, tartarughe e squali tornano.",
   oggi: "L'IPCC indica che con 1,5 °C si perde il 70–90% dei coralli, con 2 °C più del 99%: ogni decimo di grado conta.",
   curiosita: "La Grande Barriera Corallina è la più grande struttura costruita da esseri viventi: si vede dallo spazio.",
   fonti: ["IPCC SR1.5 2018", "Hughes et al. 2018, Nature"]},
  {t: -0.000174, title: "L'orso polare resiste", view: [-85, 76, 2.8], certezza: "media", species: ["orso-polare"],
   img: {file: "File:Polar bear on sea ice (52791040875).jpg", author: "USFWS Alaska", lic: "Pubblico dominio", cap: "Orso polare sul ghiaccio marino", tipo: "foto"},
   text: "Con il riscaldamento fermo sotto i 2 °C, il ghiaccio marino estivo si riduce ma non scompare ogni anno, e torna a crescere quando la temperatura scende. Le popolazioni dell'alto Artico canadese e della Groenlandia resistono.",
   oggi: "Secondo l'IPCC, la perdita di ghiaccio marino artico è reversibile: se il clima si raffredda, il ghiaccio torna.",
   curiosita: "Gli orsi polari possono nuotare per giorni: una femmina seguita col radiocollare nuotò per 687 km di fila.",
   fonti: ["Molnár et al. 2020, Nature Climate Change", "Pagano et al. 2012, Polar Biology"]},
  {t: -0.000274, title: "2300: le Maldive costruiscono in alto", view: [73.5, 4.2, 6], certezza: "media",
   img: {file: "File:Hulhumale, Maldives (hulhumale).jpg", author: "NASA/USGS Landsat", lic: "Pubblico dominio", cap: "Hulhumalé, isola artificiale delle Maldive", tipo: "foto"},
   text: "Il mare continua a salire anche con poche emissioni, perché le calotte reagiscono lentamente. Le Maldive hanno costruito isole più alte e le città costiere si sono difese per tempo. Il cambiamento è lento abbastanza da permettere di adattarsi.",
   oggi: "Nel 2025 la Corte internazionale di giustizia ha stabilito che gli stati hanno l'obbligo di proteggere il clima per le generazioni future.",
   curiosita: "Le Maldive sono il paese più basso del mondo: il punto più alto naturale è a circa 2,4 metri sul mare.",
   fonti: ["IPCC AR6 WGI, capitolo 9", "ICJ, parere consultivo del 23 luglio 2025"]},
  {t: -0.01, title: "Diecimila anni: il mare più alto di qualche metro", view: [5, 52.5, 5], certezza: "media",
   text: "In diecimila anni, anche nello scenario migliore, il mare sale di circa 6–7 metri, perché una parte del ghiaccio di Groenlandia e Antartide si scioglie comunque. I Paesi Bassi, che da secoli convivono con il mare, hanno spostato dighe e città.",
   oggi: "Il Piano Delta dei Paesi Bassi programma le difese dal mare fino al 2100 e oltre.",
   curiosita: "Circa un quarto dei Paesi Bassi è sotto il livello del mare: è stato strappato al mare con dighe e mulini.",
   fonti: ["Clark et al. 2016, Nature Climate Change", "IPCC AR6 WGI"]},
  {t: -0.1, title: "La glaciazione torna", view: [-85, 60, 1.5], certezza: "media",
   img: {file: "File:Northern icesheet hg.png", author: "Hannes Grobe/AWI", lic: "CC BY 2.5", cap: "Le calotte dell'ultima glaciazione nell'emisfero nord", tipo: "mappa"},
   text: "Con poche emissioni la CO₂ in più si riassorbe prima e la prossima glaciazione arriva fra circa 100 000 anni. I ghiacci tornano a coprire il Canada e il Nord Europa, il mare si abbassa e si può di nuovo camminare dalla Francia all'Inghilterra.",
   oggi: "Gli studi sui cicli di Milanković mostrano che le emissioni di oggi decidono anche quando arriverà la prossima era glaciale.",
   curiosita: "Durante l'ultima glaciazione il fondo del Mare del Nord era una pianura abitata, il Doggerland: i pescatori trovano ancora ossa di mammut e utensili nelle reti.",
   fonti: ["Ganopolski et al. 2016, Nature"]},
  {t: -0.3, title: "Homo sapiens nello spazio?", view: [0, 0, 1], certezza: "ipotesi", species: ["fut-homo-spazio"],
   img: {file: "File:OSIRIS Mars true color.jpg", author: "ESA & MPS per il team OSIRIS", lic: "CC BY-SA 3.0 IGO", cap: "Marte fotografato dalla sonda Rosetta (ESA)", tipo: "foto"},
   text: "Se l'umanità riuscisse a vivere a lungo su Marte o nello spazio, piccoli gruppi isolati per migliaia di generazioni potrebbero cambiare: ossa diverse con meno gravità, pelle più adatta alle radiazioni. È un'ipotesi lontana: oggi nessuno sa se sarà mai possibile.",
   oggi: "Nell'aprile 2026 la missione Artemis II ha riportato astronauti attorno alla Luna, per la prima volta dal 1972.",
   curiosita: "Gli astronauti che restano mesi sulla Stazione spaziale perdono fino all'1–2% della massa delle ossa al mese.",
   fonti: ["NASA Human Research Program", "Sibonga et al. 2019"]},
  {t: -1, title: "Un milione di anni", view: [20, 10, 1], certezza: "ipotesi", species: ["fut-sapiens-terra"],
   text: "In questo futuro Homo sapiens ha superato il suo secolo più difficile. Fra un milione di anni potremmo esserci ancora, forse un po' diversi. La Terra avrà ancora barriere coralline, orsi polari, linci e foreste: perché qualcuno, nel XXI secolo, ha deciso di salvarle.",
   oggi: "L'articolo 9 della Costituzione italiana tutela l'ambiente e la biodiversità «anche nell'interesse delle future generazioni».",
   curiosita: "Le specie di mammiferi durano in media da uno a qualche milione di anni: Homo sapiens, con 300 000 anni, è ancora giovane.",
   fonti: ["Barnosky et al. 2011, Nature"]}
 ],
 markers: [
  {lat: 0.0, lon: 36.9, label: "Ol Pejeta", kind: "sito", from: -0.000004, to: -0.000007, taxon: "rinoceronte-bianco", text: "Riserva in Kenya dove vivono Najin e Fatu."},
  {lat: 38.3, lon: -4.0, label: "Sierra Morena", kind: "sito", from: -0.000007, to: -0.00001, taxon: "lince-iberica", text: "Il cuore del ritorno della lince iberica."},
  {lat: 45.49, lon: 9.19, label: "Bosco Verticale", kind: "sito", from: -0.000028, to: -0.000032, text: "Due grattacieli con circa 800 alberi."},
  {lat: -22.5, lon: -42.3, label: "Foresta Atlantica", kind: "sito", from: -0.000048, to: -0.000052, text: "Corridoi di foresta per il tamarino leone dorato."}
 ]});

